INSERT INTO `courses` (`id`, `title`, `category`, `published`, `created_by_id`, `classroom_code`, `data`, `updated_at`) VALUES
('course-1793207635177', 'ภาษาต่างประเทศ (ภาษาอังกฤษ) พต110001 ประถมศึกษา', 'cat-1793207132472', 1, 'user-admin-2', 'BB-ENG-00001', '{\"title\":\"ภาษาต่างประเทศ (ภาษาอังกฤษ) พต110001 ประถมศึกษา\",\"slug\":\"110001\",\"coverImageUrl\":\"data:image/jpeg;base64,\",\"subtitle\":\"วิชาภาษาอังกฤษระดับประถมศึกษา\",\"description\":\"เนื้อหาและบทเรียนวิชาภาษาอังกฤษเบื้องต้น\",\"category\":\"cat-1793207132472\",\"categoryNameTh\":\"ภาษาต่างประเทศ\",\"level\":\"ระดับเริ่มต้น\",\"durationHours\":1.6,\"classroomCode\":\"BB-ENG-00001\",\"createdById\":\"user-admin-2\",\"classroomCapacity\":60,\"isClassroomOpen\":true,\"instructor\":{\"name\":\"ผู้ดูแลระบบ ศูนย์ส่งเสริมการเรียนรู้ระดับอำเภอบ้านบึง\",\"title\":\"Senior Lecturer, BB FlexLearn\",\"avatar\":\"/pic/user-admin-1-72937471-3a35-4aee-9bfa-c375cc5ce353.jpg\",\"organization\":\"BB FlexLearn Digital Institute\",\"signatureName\":\"ผู้ดูแลระบบ ศูนย์ส่งเสริมการเรียนรู้ระดับอำเภอบ้านบึง\"},\"colorTheme\":{\"primary\":\"slate-900\",\"secondary\":\"indigo-600\",\"badgeBg\":\"bg-indigo-50 text-indigo-700\",\"textAccent\":\"text-indigo-600\",\"gradient\":\"from-indigo-600 to-blue-700\"},\"iconType\":\"code\",\"learningOutcomes\":[\"ฟัง พูด อ่านออกเสียง และเขียนพยัญชนะ สระ คำศัพท์ในชีวิตประจำวัน เลขจำนวนนับ และเลขลำดับในภาษาอังกฤษได้\",\"ฟัง พูด อ่าน เขียน และใช้คำนาม คำกริยา คำสรรพนาม คำบุพบท คำคุณศัพท์ และคำวิเศษณ์ได้\",\"กล่าวทักทายและตอบรับการทักทาย กล่าวลาและตอบรับการกล่าวลา พูดแนะนำตนเอง แนะนำผู้อื่น ตั้งและตอบคำถามเกี่ยวกับบุคคลอื่น เพื่อสร้างความสัมพันธ์ระหว่างบุคคลตามความเหมาะสมในโอกาสต่าง ๆ รวมทั้งตระหนักถึงมารยาทที่ดีงามได้\",\"บอก และถามตอบเกี่ยวกับสภาพอากาศ โดยใช้ประโยคอย่างง่ายได้\",\"บอกคำศัพท์เกี่ยวกับครอบครัว บ้าน สิ่งของภายในบ้าน สี และขนาด รวมถึงใช้ประโยค Simple sentence และ WH-questions ในการสนทนาได้\",\"พูดสนทนาและเขียนประโยคขอโทษได้ เห็นคุณค่าของการกล่าวคำขอโทษต่อผู้อื่น ใช้ประโยคคำสั่ง และขอร้องได้ถูกต้อง ปฏิบัติตามคำสั่งง่าย ๆ ที่ฟังหรืออ่านได้ ตระหนักถึงความเหมาะสมในการใช้คำพูดบอกคำสั่งต่อผู้อื่นอย่างเหมาะสม\",\"เข้าใจ บอกความหมายและตระหนักถึงความสำคัญของสัญลักษณ์ที่พบในชีวิตประจำวัน เช่น ป้ายบอกทาง โรงเรียน ร้านอาหาร เป็นต้น\",\"บอก เข้าใจ และแต่งประโยคอย่างง่ายเกี่ยวกับการบอกเวลา สถานที่ และทิศทาง ในชีวิตประจำวันได้\",\"บอก ระบุ คำศัพท์เกี่ยวกับอาชีพ การถาม บอก และต่อรองราคา จำนวนของสินค้า และสนทนาโต้ตอบในอาชีพค้าขายได้\"],\"requirements\":[\"สมาร์ทโฟนหรือคอมพิวเตอร์ที่เชื่อมต่ออินเทอร์เน็ตได้\"],\"published\":true,\"lessons\":[{\"id\":\"lesson-init-1793207635177\",\"title\":\"01. บทนำและภาพรวมหลักสูตร\",\"description\":\"โครงสร้างการเรียนรู้และเป้าหมายความสำเร็จ\",\"durationMinutes\":15,\"videoUrl\":\"https://youtu.be/CCClCrbnkbY?si=wC_YUL6jZK0CaLv4\",\"subLessons\":[],\"order\":1,\"keyTakeaways\":[],\"resources\":[]},{\"id\":\"lesson-1793208568288\",\"title\":\"Unit 1 Let’s Learn English มาเรียนภาษาอังกฤษกันเถอะ\",\"description\":\"คำอธิบายเนื้อหาบทเรียนและสรุปผลการเรียนรู้\",\"durationMinutes\":20,\"videoUrl\":\"https://youtu.be/yQB9bAsReJo?si=xzCBb2aDH3TVwfpq\",\"subLessons\":[{\"id\":\"sub-1793282409525\",\"title\":\"Chapter 1: Alphabets/ Vowels/ Word combinations and Numbers\",\"durationMinutes\":10,\"videoUrl\":\"https://youtu.be/yHLXrVtqAr0?si=xWTU-beVw47emL8w\",\"order\":1},{\"id\":\"sub-1793282440566\",\"title\":\"Chapter 2: Parts of speech\",\"durationMinutes\":10,\"videoUrl\":\"https://youtu.be/MjvsxIYEy9k?si=nMCi7zLZCeFKle_p\",\"order\":2}],\"order\":2,\"keyTakeaways\":[],\"resources\":[{\"id\":\"res-1793285435616\",\"title\":\"ภาอังกฤษ ประถมบทที่ 1\",\"type\":\"pdf\",\"url\":\"/uploads/mat-user-admin-1-cfdba066-6ec8-4010-8680-1bb080e3ed10.pdf\",\"size\":\"698 KB\"}]},{\"id\":\"lesson-1793208754516\",\"title\":\"Unit 2 Me and my Friends ฉันและเพื่อนของฉัน\",\"description\":\"บทเรียนออนไลน์คุณภาพสูง\",\"durationMinutes\":47,\"videoUrl\":\"https://youtu.be/yQB9bAsReJo?si=xzCBb2aDH3TVwfpq\",\"subLessons\":[{\"id\":\"sub-1793282528680\",\"title\":\"Chapter 1: Greeting\",\"durationMinutes\":15,\"videoUrl\":\"https://youtu.be/Ep6gne4H5Sg?si=QNr4mnpeW_J-O-Kk\",\